// AI food recognition with Google Gemini (your own free API key, stored only on this phone).
// Photos/descriptions go straight from the phone to Google; nothing else is sent.

import { getKV, setKV, deleteKV } from './store.js';
import { cleanNutrients } from './nutrients.js';

const API = 'https://generativelanguage.googleapis.com/v1beta';
// Bump when the automatic model choice changes, so older automatic picks are redone.
const PICK_VERSION = 'auto2';
export class AIError extends Error {
  constructor(message, { status = 0, timeout = false, detail = '' } = {}) { super(message); this.status = status; this.timeout = timeout; this.detail = detail; }
}

export const ai = {
  get key() { return getKV('gemini.key', '') || ''; },
  setKey(k) { return k ? setKV('gemini.key', k.replace(/\s+/g, '')) : deleteKV('gemini.key'); },
  get model() { return getKV('gemini.model', '') || ''; },
  /** picked = chosen by hand in AI settings (otherwise it was chosen automatically). */
  setModel(m, picked = false) {
    setKV('gemini.modelPick', m ? (picked ? 'user' : PICK_VERSION) : '');
    return m ? setKV('gemini.model', m) : deleteKV('gemini.model');
  },
  get hasKey() { return !!this.key; },
};

async function call(path, { method = 'GET', body = null, timeoutMs = 60000 } = {}) {
  if (!ai.key) throw new AIError('Add your Gemini API key first (Food → ⋯ → AI settings).');
  if (!navigator.onLine) throw new AIError('You are offline. AI analysis needs an internet connection.');
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  let res;
  try {
    // Key goes in a header (not the URL), works for both "AIza…" and newer "AQ.…" keys.
    const headers = { 'x-goog-api-key': ai.key };
    if (body) headers['Content-Type'] = 'application/json';
    res = await fetch(`${API}/${path}`, {
      method, signal: ctrl.signal, headers,
      body: body ? JSON.stringify(body) : null,
    });
  } catch (e) {
    if (e && e.name === 'AbortError') throw new AIError('Gemini took too long to answer. Try again, or choose a different model in AI settings.', { timeout: true });
    throw new AIError("Couldn't reach Google Gemini. Check your connection.");
  } finally { clearTimeout(t); }
  let j = null;
  try { j = await res.json(); } catch {}
  if (!res.ok) {
    const msg = (j && j.error && j.error.message) || '';
    const err = (text) => new AIError(text, { status: res.status, detail: `${res.status}${msg ? ' · ' + msg.slice(0, 200) : ''}` });
    if ((res.status === 400 || res.status === 401) && /api key/i.test(msg)) throw err('That API key was rejected by Google. Check it in AI settings.');
    if (res.status === 403) throw err('This API key is not allowed to use Gemini. Create a key in Google AI Studio.');
    if (res.status === 429) throw err('Free Gemini limit reached for now. Wait a minute (or until tomorrow) and try again.');
    if (res.status === 404) throw err('The selected Gemini model is unavailable. Tap “Test key” in AI settings to pick another.');
    if (res.status >= 500) throw err('Gemini is having problems right now. Try again shortly.');
    throw err(msg ? `Gemini: ${msg.slice(0, 160)}` : `Gemini error (${res.status}).`);
  }
  return j;
}

function versionOf(name) { const m = /gemini-(\d+(?:\.\d+)?)/.exec(name); return m ? parseFloat(m[1]) : 0; }

/** Lists usable models and picks the best fast one (newest stable "flash"). */
export async function discoverModels() {
  const j = await call('models?pageSize=200', { timeoutMs: 20000 });
  const models = ((j && j.models) || [])
    .filter((m) => (m.supportedGenerationMethods || []).includes('generateContent'))
    .map((m) => m.name.replace(/^models\//, ''))
    .filter((n) => /^gemini/.test(n) && !/(image|tts|audio|live|embedding|learnlm|robotics|computer-use|native)/i.test(n));
  // Prefer a stable, versioned "flash" model: fast, generous free limits. "-latest" aliases
  // and previews can point at slower experimental models, so they rank lower.
  const rank = (n) => {
    let r = versionOf(n) * 10;
    if (/flash/.test(n)) r += 100;
    if (/lite/.test(n)) r -= 30;
    if (/latest/.test(n)) r -= 40;
    if (/preview|exp|thinking/.test(n)) r -= 50;
    if (/pro/.test(n)) r -= 60; // slower and tighter free limits
    return r;
  };
  models.sort((a, b) => rank(b) - rank(a));
  return models;
}

async function modelName() {
  const pick = getKV('gemini.modelPick', '');
  if (ai.model && (pick === 'user' || pick === PICK_VERSION)) return ai.model;
  const list = await discoverModels();
  if (!list.length) throw new AIError('No Gemini models are available for this key.');
  await ai.setModel(list[0]);
  return list[0];
}

/** Resize/compress a photo to a JPEG (max 1024 px) and return base64. */
export async function imageToBase64(file, max = 1024) {
  const url = URL.createObjectURL(file);
  try {
    const img = await new Promise((resolve, reject) => { const i = new Image(); i.onload = () => resolve(i); i.onerror = () => reject(new AIError("Couldn't read that photo.")); i.src = url; });
    const s = Math.min(1, max / Math.max(img.naturalWidth, img.naturalHeight));
    const c = document.createElement('canvas');
    c.width = Math.max(1, Math.round(img.naturalWidth * s)); c.height = Math.max(1, Math.round(img.naturalHeight * s));
    c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
    const data = c.toDataURL('image/jpeg', 0.82);
    return { base64: data.split(',')[1], preview: c.toDataURL('image/jpeg', 0.5) };
  } finally { URL.revokeObjectURL(url); }
}

const NUM = { type: 'NUMBER' };
const ITEM_SCHEMA = {
  type: 'OBJECT',
  properties: {
    name: { type: 'STRING' }, portion: { type: 'STRING' }, grams: NUM, confidence: NUM,
    calories: NUM, protein_g: NUM, carbs_g: NUM, fat_g: NUM,
    fibre_g: NUM, sugars_g: NUM, saturated_fat_g: NUM, salt_g: NUM,
    vitamin_a_ug: NUM, vitamin_c_mg: NUM, vitamin_d_ug: NUM, vitamin_e_mg: NUM, vitamin_k_ug: NUM,
    thiamin_mg: NUM, riboflavin_mg: NUM, niacin_mg: NUM, vitamin_b6_mg: NUM, folate_ug: NUM, vitamin_b12_ug: NUM,
    calcium_mg: NUM, iron_mg: NUM, magnesium_mg: NUM, potassium_mg: NUM, zinc_mg: NUM, phosphorus_mg: NUM, selenium_ug: NUM, iodine_ug: NUM,
  },
  required: ['name', 'portion', 'grams', 'calories', 'protein_g', 'carbs_g', 'fat_g', 'fibre_g', 'sugars_g', 'saturated_fat_g', 'salt_g', 'confidence'],
};
const SCHEMA = {
  type: 'OBJECT',
  properties: { items: { type: 'ARRAY', items: ITEM_SCHEMA }, notes: { type: 'STRING' }, is_food: { type: 'BOOLEAN' } },
  required: ['items', 'is_food'],
};
const MAP = {
  calories: 'kcal', protein_g: 'protein', carbs_g: 'carbs', fat_g: 'fat', fibre_g: 'fibre', sugars_g: 'sugars',
  saturated_fat_g: 'satFat', salt_g: 'salt', vitamin_a_ug: 'vitA', vitamin_c_mg: 'vitC', vitamin_d_ug: 'vitD',
  vitamin_e_mg: 'vitE', vitamin_k_ug: 'vitK', thiamin_mg: 'thiamin', riboflavin_mg: 'riboflavin', niacin_mg: 'niacin',
  vitamin_b6_mg: 'vitB6', folate_ug: 'folate', vitamin_b12_ug: 'vitB12', calcium_mg: 'calcium', iron_mg: 'iron',
  magnesium_mg: 'magnesium', potassium_mg: 'potassium', zinc_mg: 'zinc', phosphorus_mg: 'phosphorus', selenium_ug: 'selenium', iodine_ug: 'iodine',
};

const SYSTEM = `You are a precise nutrition analyst for a UK food-tracking app. Identify every distinct food or drink and estimate each one's portion weight in grams (or ml for drinks) and its nutrition FOR THAT PORTION, using UK/EU food composition data (e.g. McCance & Widdowson, USDA where needed). Carbohydrate excludes fibre (UK labelling). Salt = sodium × 2.5. Split mixed plates into components (e.g. "chicken breast", "white rice", "curry sauce") unless it is one product. Use visual cues (plate ~26 cm, cutlery, hands, packaging) for size. Include cooking oil/butter/sauces you can reasonably infer. Give vitamins/minerals when you can estimate them. confidence is 0–1. If the image or text contains no food, set is_food false and return an empty items list. Keep names short (max 5 words), portion as a human description like "1 medium bowl" or "2 slices".`;

const LABEL = `This is a photo of a nutrition label / packaging. Read the values exactly as printed. Return ONE item whose grams is 100 and whose nutrition is PER 100 g (or per 100 ml), converting from per-serving if only that is printed. Put the product name (and brand if visible) in name, and the stated serving size in portion (e.g. "1 bar (45 g)"). Convert energy from kJ if needed (kcal = kJ / 4.184).`;

/** Keep "thinking" short: food estimates don't need it and it is the main cause of slow answers. */
function thinkingFor(model) {
  if (/gemini-(3|4)|latest/.test(model)) return { thinkingLevel: 'low' };
  if (/2\.5-flash/.test(model)) return { thinkingBudget: 0 };
  if (/2\.5-pro/.test(model)) return { thinkingBudget: 128 };
  return null;
}

async function generate(model, body, timeoutMs) {
  const think = getKV('gemini.noThinkCfg', '') === model ? null : thinkingFor(model);
  const withThink = think ? { ...body, generationConfig: { ...body.generationConfig, thinkingConfig: think } } : body;
  try {
    return await call(`models/${encodeURIComponent(model)}:generateContent`, { method: 'POST', body: withThink, timeoutMs });
  } catch (e) {
    // This model doesn't accept that thinking setting: remember and send without it.
    if (think && e instanceof AIError && e.status === 400 && /think/i.test(e.message)) {
      setKV('gemini.noThinkCfg', model);
      return call(`models/${encodeURIComponent(model)}:generateContent`, { method: 'POST', body, timeoutMs });
    }
    throw e;
  }
}

/** Other models to try when the first one fails (each model has its own free quota). */
async function alternatives(current) {
  try {
    const list = (await discoverModels()).filter((m) => m !== current && /flash/.test(m));
    const lite = list.filter((m) => /lite/.test(m));
    const rest = list.filter((m) => !/lite/.test(m));
    return [...lite.slice(0, 1), ...rest.slice(0, 1), ...lite.slice(1, 2)];
  } catch { return []; }
}

const SHAPE = `Reply with ONLY a JSON object, no markdown, in exactly this shape:
{"is_food": true, "notes": "", "items": [{"name": "", "portion": "", "grams": 0, "confidence": 0.8, "calories": 0, "protein_g": 0, "carbs_g": 0, "fat_g": 0, "fibre_g": 0, "sugars_g": 0, "saturated_fat_g": 0, "salt_g": 0, "vitamin_c_mg": 0, "vitamin_d_ug": 0, "calcium_mg": 0, "iron_mg": 0, "potassium_mg": 0, "magnesium_mg": 0}]}
All numbers are plain numbers. Leave out vitamin/mineral fields you cannot estimate.`;

function parseJSON(raw) {
  const t = String(raw || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { return JSON.parse(t); } catch {}
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch {} }
  return null;
}

/**
 * mode: 'photo' | 'label' | 'text'. onStatus(text) reports progress.
 * Tries the chosen model, then a simpler request, then other models, so one busy or
 * failing model doesn't stop you logging.
 * Returns { items: [{name, portion, grams, confidence, base(per 100 g), totals}], notes, model }.
 */
export async function analyse({ mode, image = null, text = '', onStatus = () => {} }) {
  let prompt;
  if (mode === 'label') prompt = LABEL + (text ? `\nExtra info from the user: ${text}` : '');
  else if (mode === 'text') prompt = `Estimate the nutrition of what I ate: ${text}`;
  else prompt = 'Identify the foods in this photo and estimate portions and nutrition.' + (text ? ` Extra details from me: ${text}` : '');
  const build = (simple) => {
    const parts = [];
    if (image) parts.push({ inline_data: { mime_type: 'image/jpeg', data: image } });
    parts.push({ text: simple ? `${prompt}\n\n${SHAPE}` : prompt });
    const generationConfig = simple
      ? { temperature: 0.2, responseMimeType: 'application/json' }
      : { temperature: 0.2, responseMimeType: 'application/json', responseSchema: SCHEMA };
    return { systemInstruction: { parts: [{ text: SYSTEM }] }, contents: [{ role: 'user', parts }], generationConfig };
  };
  const { data, model } = await askJSON(build, onStatus);
  return { ...parseResult(data), model };
}

/**
 * Sends a JSON request, trying the chosen model, then a simpler request, then other models,
 * so one busy or failing model doesn't stop you. build(simple) returns the request body.
 */
async function askJSON(build, onStatus = () => {}) {
  let model = await modelName();
  const simpleFirst = getKV('gemini.simple', '') === model;
  const plan = [{ model, simple: simpleFirst }, { model, simple: !simpleFirst }];
  let alts = null;
  let lastErr = null;
  for (let i = 0; i < plan.length && i < 5; i++) {
    const step = plan[i];
    if (i > 0) onStatus(step.model === model ? `${model} had a problem — trying a simpler request…` : `Trying ${step.model}…`);
    let j;
    try { j = await generate(step.model, build(step.simple), i === 0 ? 45000 : 40000); }
    catch (e) {
      if (!(e instanceof AIError)) throw e;
      lastErr = e;
      if (e.status === 404 && i === 0 && ai.model) {
        // A stale saved model: forget it and start again with a freshly discovered one.
        await ai.setModel('');
        model = await modelName();
        plan.push({ model, simple: false });
        continue;
      }
      const retryable = e.timeout || e.status >= 500 || e.status === 429 || (e.status === 400 && !/api key/i.test(e.message));
      if (!retryable) throw e;
      if (alts == null && i >= 1) {
        alts = await alternatives(model);
        for (const m of alts) plan.push({ model: m, simple: true });
      }
      continue;
    }
    const cand = j && j.candidates && j.candidates[0];
    if (!cand) {
      const block = j && j.promptFeedback && j.promptFeedback.blockReason;
      if (block) throw new AIError(`Gemini refused this request (${block}).`);
      lastErr = new AIError('Gemini returned no answer.'); continue;
    }
    const raw = (cand.content && cand.content.parts || []).filter((p) => !p.thought).map((p) => p.text || '').join('');
    const data = parseJSON(raw);
    if (!data) { lastErr = new AIError(cand.finishReason === 'MAX_TOKENS' ? 'Gemini’s answer was cut off.' : "Gemini's answer couldn't be read.", { detail: `finish: ${cand.finishReason || '?'}` }); continue; }
    // Remember what worked so the next request goes straight there.
    if (step.model !== ai.model && getKV('gemini.modelPick', '') !== 'user') await ai.setModel(step.model);
    if (step.simple) setKV('gemini.simple', step.model); else if (getKV('gemini.simple', '') === step.model) deleteKV('gemini.simple');
    return { data, model: step.model };
  }
  const e = lastErr || new AIError('Gemini returned no answer.');
  const tried = [...new Set(plan.map((p) => p.model))].join(', ');
  throw new AIError(`${e.message.replace(/ Try again.*$/, '')} Tried: ${tried}. Try again in a minute.`, { status: e.status, detail: e.detail });
}

// ---------------------------------------------------------------------------------
// "Fill the gap": meal ideas that fit what's left of today's targets

const SUGGEST_ITEM = {
  type: 'OBJECT',
  properties: {
    name: { type: 'STRING' }, portion: { type: 'STRING' }, grams: NUM,
    calories: NUM, protein_g: NUM, carbs_g: NUM, fat_g: NUM, fibre_g: NUM, sugars_g: NUM, saturated_fat_g: NUM, salt_g: NUM,
  },
  required: ['name', 'portion', 'grams', 'calories', 'protein_g', 'carbs_g', 'fat_g'],
};
const SUGGEST_SCHEMA = {
  type: 'OBJECT',
  properties: {
    options: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: { title: { type: 'STRING' }, why: { type: 'STRING' }, prep_minutes: NUM, items: { type: 'ARRAY', items: SUGGEST_ITEM } },
        required: ['title', 'why', 'items'],
      },
    },
  },
  required: ['options'],
};
const SUGGEST_SHAPE = `Reply with ONLY a JSON object, no markdown, in exactly this shape:
{"options": [{"title": "", "why": "", "prep_minutes": 5, "items": [{"name": "", "portion": "", "grams": 0, "calories": 0, "protein_g": 0, "carbs_g": 0, "fat_g": 0, "fibre_g": 0, "sugars_g": 0, "saturated_fat_g": 0, "salt_g": 0}]}]}`;

const SUGGEST_SYSTEM = `You are a practical sports nutrition coach for a UK food-tracking app. Suggest real, simple foods and meals available in UK supermarkets or easy to make at home, with realistic portions in grams and accurate UK nutrition values. Each option must fit the remaining targets as closely as possible: hit the protein, carbs and fat gaps while keeping total calories within about 10% of the calories left, and keep under any stated limits (sugar, saturated fat, salt). Prefer whole foods; at most one item may be a protein shake or bar. Never suggest supplements other than plain protein powder, alcohol, or energy drinks. Give 3 to 5 different options (e.g. a quick no-cook one, a proper meal, a snack combo), ordered best fit first. "why" is one short sentence on how it fills the gap. Keep names short.`;

/**
 * remaining: { kcal, protein, carbs, fat, fibre, sugarsLeft, satFatLeft, saltLeft }
 * context: { meal, dayLabel, diet, timeOfDay, likes: [food names], note }
 */
export async function suggestMeals({ remaining, context = {}, onStatus = () => {} }) {
  const r = remaining;
  const lines = [
    `Calories left today: ${Math.round(r.kcal)} kcal.`,
    `Still needed: protein ${Math.max(0, Math.round(r.protein))} g, carbs ${Math.max(0, Math.round(r.carbs))} g, fat ${Math.max(0, Math.round(r.fat))} g${r.fibre > 0 ? `, fibre ${Math.round(r.fibre)} g` : ''}.`,
    `Stay under: ${[r.sugarsLeft != null ? `sugars ${Math.max(0, Math.round(r.sugarsLeft))} g` : null, r.satFatLeft != null ? `saturated fat ${Math.max(0, Math.round(r.satFatLeft))} g` : null, r.saltLeft != null ? `salt ${Math.max(0, r.saltLeft).toFixed(1)} g` : null].filter(Boolean).join(', ') || 'no extra limits'}.`,
  ];
  if (context.meal) lines.push(`It's for: ${context.meal}${context.timeOfDay ? ` (time now ${context.timeOfDay})` : ''}.`);
  if (context.dayLabel) lines.push(`Today is: ${context.dayLabel}.`);
  if (context.diet) lines.push(`Diet style: ${context.diet}.`);
  if (context.likes && context.likes.length) lines.push(`Foods I often eat (use some if they fit): ${context.likes.slice(0, 25).join(', ')}.`);
  if (context.note) lines.push(`My request: ${context.note}`);
  if (context.split) lines.push('The gap is large, so this can be split across more than one meal: make options that cover about half of it, as one meal.');
  const prompt = lines.join('\n');
  const build = (simple) => ({
    systemInstruction: { parts: [{ text: SUGGEST_SYSTEM }] },
    contents: [{ role: 'user', parts: [{ text: simple ? `${prompt}\n\n${SUGGEST_SHAPE}` : prompt }] }],
    generationConfig: simple
      ? { temperature: 0.6, responseMimeType: 'application/json' }
      : { temperature: 0.6, responseMimeType: 'application/json', responseSchema: SUGGEST_SCHEMA },
  });
  const { data, model } = await askJSON(build, onStatus);
  const options = (Array.isArray(data && data.options) ? data.options : []).map((o) => {
    const parsed = parseResult({ items: Array.isArray(o.items) ? o.items.map((it) => ({ ...it, confidence: null })) : [] }).items;
    const totals = {};
    for (const it of parsed) for (const [k, v] of Object.entries(it.totals)) totals[k] = (totals[k] || 0) + v;
    return {
      title: String(o.title || 'Meal idea').slice(0, 60), why: String(o.why || '').slice(0, 200),
      prep: Number(o.prep_minutes) > 0 ? Math.round(Number(o.prep_minutes)) : null, items: parsed, totals,
    };
  }).filter((o) => o.items.length);
  if (!options.length) throw new AIError('Gemini didn’t come up with any ideas. Try again.');
  return { options, model };
}

export function parseResult(data) {
  const items = (Array.isArray(data && data.items) ? data.items : []).map((it) => {
    const totals = {};
    for (const [k, v] of Object.entries(MAP)) if (it[k] != null) totals[v] = Number(it[k]);
    const t = cleanNutrients(totals);
    const grams = Number(it.grams) > 0 ? Number(it.grams) : null;
    // Store per 100 g so the portion can be adjusted afterwards.
    const base = grams ? Object.fromEntries(Object.entries(t).map(([k, v]) => [k, (v * 100) / grams])) : t;
    return {
      name: String(it.name || 'Food').slice(0, 60), portion: String(it.portion || '').slice(0, 60),
      grams, confidence: Number.isFinite(Number(it.confidence)) ? Number(it.confidence) : null, base, totals: t,
    };
  }).filter((x) => x.totals.kcal != null);
  return { items, notes: data && data.notes ? String(data.notes).slice(0, 400) : '', isFood: data ? data.is_food !== false : false };
}

// Nutrition goals: body inputs (read-only from the Body tab), BMR/TDEE, calorie & macro
// targets, training-day calorie cycling, adaptive TDEE from weigh-ins + intake, and BMI.

import { Q, Calendar } from '../engine.js';
import { getKV, setKV } from './store.js';
import { NUTRIENTS, N, F } from './nutrients.js';
import { planDay, dayMacros } from './plan.js';
import { addDaysKey, todayKey, parseDay, MS_DAY, sum, clamp } from '../util.js';

export const ACTIVITY = [
  [1.2, 'Sedentary', 'Desk job, little exercise'],
  [1.375, 'Lightly active', 'Light exercise 1–3 days a week'],
  [1.55, 'Moderately active', 'Training 3–5 days a week'],
  [1.725, 'Very active', 'Hard training 6–7 days a week'],
  [1.9, 'Extremely active', 'Physical job plus hard training'],
];
export const GOALS = [['lose', 'Lose fat'], ['maintain', 'Maintain'], ['gain', 'Build muscle']];
export const RATES = [0.1, 0.25, 0.5, 0.75, 1];
const KCAL_PER_KG = 7700;

/** Diet-style fields a preset can set (see diets.js). */
export const DIET_DEFAULTS = {
  macroMode: 'perkg', proteinPerKg: 1.8, fatPct: 25, carbCap: 100, pct: { protein: 30, carbs: 40, fat: 30 },
  fibre: 30, sugarLimit: 90, satFatPct: 10, saltLimit: 6, nutrients: {}, window: null,
};
export const MACRO_MODES = [['perkg', 'Protein per kg + fat %'], ['carbcap', 'Fixed carbs (low carb / keto)'], ['percent', 'Percent split']];

export const DEFAULT_PROFILE = {
  sex: null, activity: 1.55, goal: 'maintain', rate: 0.5,
  ...DIET_DEFAULTS, diet: 'balanced',
  targetWeightKg: null, targetDate: null, startWeightKg: null, startDate: null,
  adaptive: true, cycling: false, cycleKcal: 200, useBodyFat: true,
  manual: { weightKg: null, heightCm: null, age: null },
  overrides: {}, waterMl: null, waterTrainingMl: 500,
};

export function profile() {
  const p = getKV('profile', {}) || {};
  return {
    ...DEFAULT_PROFILE, ...p, manual: { ...DEFAULT_PROFILE.manual, ...(p.manual || {}) }, overrides: { ...(p.overrides || {}) },
    pct: { ...DIET_DEFAULTS.pct, ...(p.pct || {}) }, nutrients: { ...(p.nutrients || {}) },
  };
}
export function updateProfile(patch) { return setKV('profile', { ...profile(), ...patch }); }
export const isConfigured = () => !!getKV('profile', null) && !!profile().sex;

// ---------------------------------------------------------------------------------
// Body inputs: latest Body-tab check-in values (never modified here), manual fallback.

export function bodyInputs(p = profile()) {
  const entries = Q.bodyStats(); // newest first
  const w = entries.find((e) => e.weightKg != null);
  const h = entries.find((e) => e.heightInches);
  const a = entries.find((e) => e.age != null);
  const bf = entries.find((e) => e.bodyFatPercent != null && Date.now() - e.date < 120 * MS_DAY);
  const ageNow = a ? a.age + Math.floor((Date.now() - a.date) / (365.25 * MS_DAY)) : null;
  return {
    weightKg: w ? w.weightKg : p.manual.weightKg,
    heightCm: h ? h.heightInches * 2.54 : p.manual.heightCm,
    age: ageNow != null ? ageNow : p.manual.age,
    bodyFat: bf ? bf.bodyFatPercent : null,
    fromBody: { weight: !!w, height: !!h, age: !!a },
    weightDate: w ? w.date : null,
  };
}

// ---------------------------------------------------------------------------------
// Formulas

export function bmi(weightKg, heightCm) {
  if (!weightKg || !heightCm) return null;
  const m = heightCm / 100;
  return weightKg / (m * m);
}
export function bmiBand(v) {
  if (v == null) return null;
  return v < 18.5 ? ['Underweight', 'partial'] : v < 25 ? ['Healthy', 'completed'] : v < 30 ? ['Overweight', 'partial'] : ['Obese', 'missed'];
}
export function healthyWeightRange(heightCm) {
  if (!heightCm) return null;
  const m2 = (heightCm / 100) ** 2;
  return [18.5 * m2, 24.9 * m2];
}
/** Mifflin-St Jeor, or Katch-McArdle when body fat is known. */
export function bmr({ weightKg, heightCm, age, sex, bodyFat }, useBodyFat = true) {
  if (useBodyFat && bodyFat != null && weightKg) {
    const lbm = weightKg * (1 - bodyFat / 100);
    return { value: 370 + 21.6 * lbm, method: 'Katch-McArdle' };
  }
  if (!weightKg || !heightCm || age == null) return null;
  const s = sex === 'female' ? -161 : sex === 'male' ? 5 : -78;
  return { value: 10 * weightKg + 6.25 * heightCm - 5 * age + s, method: 'Mifflin-St Jeor' };
}

/** Least-squares slope (y per x). */
function slope(points) {
  const n = points.length;
  if (n < 2) return null;
  const mx = sum(points, (p) => p.x) / n, my = sum(points, (p) => p.y) / n;
  let num = 0, den = 0;
  for (const p of points) { num += (p.x - mx) * (p.y - my); den += (p.x - mx) ** 2; }
  return den ? num / den : null;
}

/** Adaptive TDEE from the last 4 weeks of logged intake and weigh-ins. */
export function adaptiveTDEE(formulaTDEE, today = todayKey()) {
  const end = addDaysKey(today, -1); // today is still in progress
  const start = addDaysKey(today, -28);
  const byDay = F.totalsByDay(start, end);
  const threshold = Math.max(800, (formulaTDEE || 2000) * 0.5);
  const logged = [...byDay.values()].map((d) => d.totals.kcal || 0).filter((k) => k >= threshold);
  const startMs = parseDay(addDaysKey(today, -35)).getTime();
  const weights = Q.bodyStats(false).filter((e) => e.weightKg != null && e.date >= startMs)
    .map((e) => ({ x: e.date / MS_DAY, y: e.weightKg }));
  const span = weights.length >= 2 ? weights[weights.length - 1].x - weights[0].x : 0;
  const status = {
    loggedDays: logged.length, weighIns: weights.length, spanDays: Math.round(span),
    ready: false, value: null, confidence: 0, avgIntake: logged.length ? sum(logged) / logged.length : null, weeklyChangeKg: null,
  };
  if (logged.length < 10 || weights.length < 2 || span < 10 || !formulaTDEE) return status;
  const s = slope(weights); // kg per day
  if (s == null) return status;
  let value = status.avgIntake - s * KCAL_PER_KG;
  value = clamp(value, formulaTDEE * 0.6, formulaTDEE * 1.5);
  status.ready = true;
  status.value = value;
  status.weeklyChangeKg = s * 7;
  status.confidence = Math.min(1, logged.length / 21) * Math.min(1, span / 21);
  return status;
}

export function trainingDaysPerWeek() {
  return new Set(Q.routines().filter((r) => r.weekday).map((r) => r.weekday)).size;
}
export const isTrainingDay = (day) => !!Calendar.routineFor(day);

const round = (v, to = 1) => Math.round(v / to) * to;

/** Everything the Goals screen shows, plus per-nutrient targets for a given day. */
export function compute(day = todayKey(), p = profile()) {
  const body = bodyInputs(p);
  const B = bmr({ ...body, sex: p.sex }, p.useBodyFat);
  const formula = B ? B.value * p.activity : null;
  const adaptive = adaptiveTDEE(formula, todayKey());
  const tdee = formula == null ? null : (p.adaptive && adaptive.ready ? formula + (adaptive.value - formula) * adaptive.confidence : formula);
  const plan = weightPlan(p, body);
  const rate = plan.rate;
  const delta = p.goal === 'lose' ? -rate * KCAL_PER_KG / 7 : p.goal === 'gain' ? rate * KCAL_PER_KG / 7 : 0;
  const floor = p.sex === 'male' ? 1500 : 1200;
  let base = tdee == null ? 2000 : tdee + delta;
  const floored = base < floor;
  base = Math.max(floor, base);

  const T = trainingDaysPerWeek();
  const training = isTrainingDay(day);
  let kcal = base, trainKcal = base, restKcal = base;
  if (p.cycling && T > 0 && T < 7) {
    trainKcal = base + p.cycleKcal;
    restKcal = base - (p.cycleKcal * T) / (7 - T);
    kcal = training ? trainKcal : restKcal;
  }
  // An imported weekly plan sets each weekday's calories (and protein/fat) directly.
  const pd = p.plan ? planDay(p.plan, day) : null;
  if (pd) kcal = pd.kcal;
  const ov = p.overrides || {};
  if (ov.kcal != null) kcal = ov.kcal;
  kcal = round(kcal, 10);

  const weight = body.weightKg || 75;
  const targets = { kcal, ...macroTargets(p, kcal, weight) };
  if (pd) {
    const hasMacros = p.plan.protein != null || p.plan.fat != null || Object.keys(pd.targets || {}).some((k) => ['protein', 'carbs', 'fat'].includes(k));
    if (hasMacros) {
      const m = dayMacros(p.plan, { ...pd, kcal }, targets.protein);
      targets.protein = m.protein; targets.carbs = Math.max(0, m.carbs); targets.fat = Math.max(0, m.fat);
    }
  }
  for (const k of ['protein', 'carbs', 'fat']) if (ov[k] != null) targets[k] = ov[k];
  targets.fibre = ov.fibre ?? p.fibre;
  targets.sugars = ov.sugars ?? p.sugarLimit;
  targets.satFat = ov.satFat ?? round(kcal * (p.satFatPct / 100) / 9);
  targets.salt = ov.salt ?? p.saltLimit;
  for (const n of NUTRIENTS) if (n.nrv != null) targets[n.key] = ov[n.key] ?? (p.nutrients[n.key] ?? n.nrv);
  // Plan-wide nutrient targets, then the day's own (your custom targets in Goals still win).
  if (pd) {
    for (const src of [p.plan.nutrients || {}, pd.targets || {}]) {
      for (const [k, v] of Object.entries(src)) if (!['protein', 'carbs', 'fat', 'kcal'].includes(k) && ov[k] == null) targets[k] = v;
    }
  }
  const waterBase = p.waterMl ?? round(35 * weight, 50);
  targets.water = pd ? (p.plan.water ?? waterBase) + (pd.water || 0) : waterBase + (training ? (p.waterTrainingMl || 0) : 0);

  return {
    day, body, bmr: B, formulaTDEE: formula, adaptive, tdee, delta, floored, floor, training, trainingDays: T,
    trainKcal: round(trainKcal, 10), restKcal: round(restKcal, 10), baseKcal: round(base, 10), targets, plan, planDay: pd,
    bmi: bmi(body.weightKg, body.heightCm), hasBody: !!(body.weightKg && body.heightCm && body.age != null),
  };
}

export const targetsFor = (day) => compute(day).targets;

/** Protein / carbs / fat in grams for a calorie target under the profile's macro method. */
export function macroTargets(p, kcal, weight) {
  if (p.macroMode === 'percent') {
    const t = (p.pct.protein || 0) + (p.pct.carbs || 0) + (p.pct.fat || 0) || 100;
    return {
      protein: round((kcal * (p.pct.protein / t)) / 4), carbs: round((kcal * (p.pct.carbs / t)) / 4), fat: round((kcal * (p.pct.fat / t)) / 9),
    };
  }
  const protein = round(p.proteinPerKg * weight);
  if (p.macroMode === 'carbcap') {
    const carbs = round(p.carbCap);
    return { protein, carbs, fat: Math.max(30, round((kcal - protein * 4 - carbs * 4) / 9)) };
  }
  const fat = round((p.fatPct / 100) * kcal / 9);
  return { protein, fat, carbs: Math.max(0, round((kcal - protein * 4 - fat * 9) / 4)) };
}

/**
 * Target weight plan: the weekly rate actually used (from a target date when set, kept within
 * safe limits), progress and the estimated finish date.
 */
export function weightPlan(p, body = bodyInputs(p)) {
  const w = body.weightKg;
  const out = { rate: p.rate, target: p.targetWeightKg, current: w, start: p.startWeightKg, byDate: false, capped: false, eta: null, toGo: null, progress: null, mismatch: false, reached: false };
  if (p.goal === 'maintain' || !p.targetWeightKg || !w) return out;
  const diff = p.targetWeightKg - w; // negative = need to lose
  out.toGo = Math.abs(diff);
  out.mismatch = (p.goal === 'lose' && diff > 0.05) || (p.goal === 'gain' && diff < -0.05);
  out.reached = !out.mismatch && Math.abs(diff) < 0.3;
  const maxRate = p.goal === 'lose' ? Math.max(0.25, Math.min(1, w * 0.01)) : 0.75;
  if (p.targetDate && !out.mismatch && !out.reached) {
    const weeks = Math.max(1, (parseDay(p.targetDate) - parseDay(todayKey())) / (7 * MS_DAY));
    const need = Math.abs(diff) / weeks;
    out.byDate = true;
    out.rate = Math.min(maxRate, Math.max(0.05, need));
    out.capped = need > maxRate;
  }
  if (!out.mismatch && !out.reached && out.rate > 0) {
    out.eta = Date.now() + (Math.abs(diff) / out.rate) * 7 * MS_DAY;
  }
  if (p.startWeightKg != null && Math.abs(p.startWeightKg - p.targetWeightKg) > 0.05) {
    out.progress = clamp((p.startWeightKg - w) / (p.startWeightKg - p.targetWeightKg), 0, 1);
  }
  return out;
}
export const kindOf = (key) => (N[key] ? N[key].kind : 'target');

// Weekly eating plan: a readable text you can paste in (and edit), giving every weekday its own
// calories, macros and nutrient targets, plus a weight path with weekly milestones.
//
// Format (one item per line, # starts a comment):
//   GYMOS PLAN
//   name: Road to 95
//   start: 2026-11-10 105        (date, starting weight kg)
//   target: 95                   (target weight kg)
//   rate: 0.4                    (kg per week)
//   protein: 160                 (g every day unless a day says otherwise)
//   fat: 80                      (g every day; carbs fill the rest)
//   water: 3000                  (ml every day)
//   fibre: 30   calcium: 1000    (any nutrient target for every day)
//   mon: 2600 School walk        (calories, then a label; "+500ml" adds water that day)
//   tue: 2800 Lifting | protein 190 carbs 330 fibre 35
//                                (after "|": that day's own targets; the one macro left out fills the calories)
//   tip: Eat 3 meals with protein.

import { todayKey, parseDay, addDaysKey, MS_DAY, weekday, dayKey } from '../util.js';
import { NUTRIENTS, N } from './nutrients.js';

const DAYS = { sun: 1, mon: 2, tue: 3, wed: 4, thu: 5, fri: 6, sat: 7 };
const DAY_NAMES = ['', 'sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
export const DAY_ORDER = [2, 3, 4, 5, 6, 7, 1];
const MACROS = ['protein', 'carbs', 'fat'];

// Words accepted for each nutrient (lower case, spaces removed).
const ALIASES = { carb: 'carbs', carbohydrate: 'carbs', carbohydrates: 'carbs', fiber: 'fibre', sugar: 'sugars',
  satfat: 'satFat', saturatedfat: 'satFat', saturates: 'satFat', sodium: null, kcal: 'kcal', calories: 'kcal' };
for (const n of NUTRIENTS) {
  ALIASES[n.key.toLowerCase()] = n.key;
  ALIASES[n.label.toLowerCase().replace(/\(.*?\)/g, '').replace(/[^a-z0-9]/g, '')] = n.key;
}
ALIASES.vitamind = 'vitD'; ALIASES.vitaminc = 'vitC'; ALIASES.vitamina = 'vitA'; ALIASES.b12 = 'vitB12'; ALIASES.vitaminb12 = 'vitB12';
const nutrientKey = (word) => { const k = String(word).toLowerCase().replace(/[^a-z0-9]/g, ''); return k in ALIASES ? ALIASES[k] : undefined; };

export class PlanError extends Error {}

const num = (v, what, lo, hi) => {
  const x = Number(String(v).replace(',', '.'));
  if (!Number.isFinite(x) || x < lo || x > hi) throw new PlanError(`${what} must be a number between ${lo} and ${hi}.`);
  return x;
};
const LIMITS = { protein: [20, 400], carbs: [0, 900], fat: [15, 300] };
function nutrientValue(key, v) {
  const [lo, hi] = LIMITS[key] || [0, 100000];
  return num(v, N[key] ? N[key].label : key, lo, hi);
}

/** "protein 190 carbs 330 sat fat 25" → { protein: 190, carbs: 330, satFat: 25 } */
function parseTargets(text, where) {
  const out = {};
  const re = /([a-z][a-z ]*?)\s*[:=]?\s*(\d+(?:[.,]\d+)?)\s*(?:g|mg|µg|ug|mcg)?(?=\s|$|,|;)/gi;
  let m; let any = false;
  while ((m = re.exec(text))) {
    const k = nutrientKey(m[1]);
    if (k === undefined || k === null) throw new PlanError(`${where}: unknown nutrient “${m[1].trim()}”.`);
    if (k === 'kcal') throw new PlanError(`${where}: put calories straight after the day name.`);
    out[k] = nutrientValue(k, m[2]);
    any = true;
  }
  if (!any && text.trim()) throw new PlanError(`${where}: write targets like “protein 190 carbs 330”.`);
  return out;
}

export function parsePlan(text) {
  const lines = String(text || '').split(/\r?\n/).map((l) => l.replace(/#.*$/, '').trim()).filter(Boolean);
  if (!lines.length) throw new PlanError('The plan is empty.');
  const plan = { name: 'My plan', days: {}, tips: [], nutrients: {} };
  for (const line of lines) {
    if (/^gymos plan$/i.test(line)) continue;
    const m = /^([a-z][a-z0-9 ()]*?)\s*:\s*(.*)$/i.exec(line);
    if (!m) throw new PlanError(`Couldn't read this line: “${line.slice(0, 40)}”`);
    const key = m[1].toLowerCase().replace(/\s+/g, ' ').trim(); const val = m[2].trim();
    if (key === 'name') plan.name = val.slice(0, 40) || plan.name;
    else if (key === 'start') {
      const s = /^(\d{4}-\d{2}-\d{2})\s+([\d.,]+)/.exec(val);
      if (!s) throw new PlanError('start needs a date and a weight, e.g. “start: 2026-11-10 105”.');
      plan.startDate = s[1]; plan.startWeightKg = num(s[2], 'Start weight', 30, 300);
    } else if (key === 'target') plan.targetWeightKg = num(val, 'Target weight', 30, 300);
    else if (key === 'rate') plan.rate = num(val, 'Rate', 0.05, 1);
    else if (key === 'protein') plan.protein = nutrientValue('protein', val);
    else if (key === 'fat') plan.fat = nutrientValue('fat', val);
    else if (key === 'water') plan.water = num(val, 'Water', 500, 8000);
    else if (key === 'tip') plan.tips.push(val.slice(0, 160));
    else if (DAYS[key]) {
      const [main, extra = ''] = val.split('|');
      const d = /^(\d{3,5})\s*(.*)$/.exec(main.trim());
      if (!d) throw new PlanError(`${key} needs calories first, e.g. “${key}: 2600 School walk”.`);
      const kcal = num(d[1], `${key} calories`, 1000, 6000);
      let label = d[2].trim();
      let water = 0;
      const w = /\+\s*(\d{2,4})\s*ml/i.exec(label);
      if (w) { water = Number(w[1]); label = label.replace(w[0], '').replace(/\(\s*\)/g, '').trim(); }
      const t = parseTargets(extra, key);
      const given = MACROS.filter((k) => t[k] != null);
      if (given.length === 3) {
        const sum = t.protein * 4 + t.carbs * 4 + t.fat * 9;
        if (Math.abs(sum - kcal) > 150) throw new PlanError(`${key}: protein, carbs and fat add up to ${Math.round(sum)} kcal, not ${kcal}. Leave one out and it will fill the rest.`);
      }
      plan.days[DAYS[key]] = { kcal, label: label.slice(0, 40), water, targets: t };
    } else {
      const k = nutrientKey(key);
      if (k === undefined || k === null || k === 'kcal') throw new PlanError(`Unknown setting “${key}”.`);
      if (k === 'carbs') throw new PlanError('Set carbs per day (after “|”), or leave them to fill the calories.');
      plan.nutrients[k] = nutrientValue(k, val);
    }
  }
  const missing = DAY_ORDER.filter((wd) => !plan.days[wd]).map((wd) => DAY_NAMES[wd]);
  if (missing.length) throw new PlanError(`Add a calorie target for: ${missing.join(', ')}.`);
  if (plan.targetWeightKg != null && plan.startWeightKg == null) throw new PlanError('Add a start line, e.g. “start: 2026-11-10 105”.');
  if (plan.rate == null && plan.targetWeightKg != null) plan.rate = 0.4;
  // Every day must leave something sensible for the macro that fills the rest.
  for (const wd of DAY_ORDER) {
    const m = dayMacros(plan, plan.days[wd], 75);
    if (m.carbs < 0 || m.fat < 15) throw new PlanError(`${DAY_NAMES[wd]}: the macros don't fit in ${plan.days[wd].kcal} kcal. Lower protein/fat or raise calories.`);
  }
  return plan;
}

/**
 * Protein / carbs / fat for one plan day. The day's own numbers win, then the plan-wide ones;
 * whichever macro is still missing (carbs first) fills the day's calories.
 */
export function dayMacros(plan, d, fallbackProtein) {
  const t = d.targets || {};
  const m = { protein: t.protein ?? plan.protein ?? fallbackProtein, carbs: t.carbs ?? null, fat: t.fat ?? null };
  if (m.carbs == null && m.fat == null) m.fat = plan.fat ?? Math.round((d.kcal * 0.25) / 9);
  if (m.carbs == null) m.carbs = Math.round((d.kcal - m.protein * 4 - m.fat * 9) / 4);
  else if (m.fat == null) m.fat = Math.round((d.kcal - m.protein * 4 - m.carbs * 4) / 9);
  else if (t.protein == null && plan.protein == null) m.protein = Math.round((d.kcal - m.carbs * 4 - m.fat * 9) / 4);
  return m;
}

const fmtNum = (v) => String(Math.round(v * 100) / 100);
function targetsText(t) {
  return Object.entries(t || {}).map(([k, v]) => `${k === 'satFat' ? 'satfat' : k.toLowerCase()} ${fmtNum(v)}`).join(' ');
}

export function planToText(plan) {
  const out = ['GYMOS PLAN', `name: ${plan.name}`];
  if (plan.startDate) out.push(`start: ${plan.startDate} ${plan.startWeightKg}`);
  if (plan.targetWeightKg != null) out.push(`target: ${plan.targetWeightKg}`);
  if (plan.rate != null) out.push(`rate: ${plan.rate}`);
  if (plan.protein != null) out.push(`protein: ${plan.protein}`);
  if (plan.fat != null) out.push(`fat: ${plan.fat}`);
  if (plan.water != null) out.push(`water: ${plan.water}`);
  for (const [k, v] of Object.entries(plan.nutrients || {})) out.push(`${k === 'satFat' ? 'satfat' : k.toLowerCase()}: ${fmtNum(v)}`);
  for (const wd of DAY_ORDER) {
    const d = plan.days[wd];
    const extra = targetsText(d.targets);
    out.push(`${DAY_NAMES[wd]}: ${d.kcal}${d.label ? ' ' + d.label : ''}${d.water ? ` +${d.water}ml` : ''}${extra ? ` | ${extra}` : ''}`);
  }
  for (const t of plan.tips || []) out.push(`tip: ${t}`);
  return out.join('\n');
}

export const planDay = (plan, day = todayKey()) => (plan ? plan.days[weekday(day)] || null : null);
export const weeklyAverage = (plan) => DAY_ORDER.reduce((a, wd) => a + plan.days[wd].kcal, 0) / 7;

/** Expected weight on a date if the plan runs at its rate (never past the target). */
export function expectedWeight(plan, day) {
  if (!plan || plan.startWeightKg == null || plan.targetWeightKg == null) return null;
  const weeks = Math.max(0, (parseDay(day) - parseDay(plan.startDate)) / (7 * MS_DAY));
  const dir = plan.targetWeightKg < plan.startWeightKg ? -1 : 1;
  const w = plan.startWeightKg + dir * plan.rate * weeks;
  return dir < 0 ? Math.max(plan.targetWeightKg, w) : Math.min(plan.targetWeightKg, w);
}

export function finishDate(plan) {
  if (!plan || plan.targetWeightKg == null) return null;
  const weeks = Math.abs(plan.startWeightKg - plan.targetWeightKg) / plan.rate;
  return addDaysKey(plan.startDate, Math.ceil(weeks * 7));
}

/** Milestones every `every` weeks from the start to the target. */
export function milestones(plan, every = 4) {
  const end = finishDate(plan);
  if (!end) return [];
  const out = [];
  for (let k = every; ; k += every) {
    const d = addDaysKey(plan.startDate, k * 7);
    if (d >= end) { out.push({ day: end, weight: plan.targetWeightKg, week: Math.ceil((parseDay(end) - parseDay(plan.startDate)) / (7 * MS_DAY)) }); break; }
    out.push({ day: d, weight: expectedWeight(plan, d), week: k });
    if (out.length > 60) break;
  }
  return out;
}

/** Where you are against the plan: latest weigh-in vs the expected weight on that day. */
export function planStatus(plan, latestWeight, latestDate) {
  if (!plan || plan.targetWeightKg == null || latestWeight == null || !latestDate) return null;
  const day = dayKey(latestDate);
  if (day < plan.startDate) return null;
  const expected = expectedWeight(plan, day);
  const losing = plan.targetWeightKg < plan.startWeightKg;
  const diff = losing ? latestWeight - expected : expected - latestWeight; // > 0 = behind
  const week = Math.floor((parseDay(todayKey()) - parseDay(plan.startDate)) / (7 * MS_DAY)) + 1;
  return { expected, diff, week, state: diff > 0.75 ? 'behind' : diff < -0.75 ? 'ahead' : 'on' };
}

/** Ready-made plan: start 105 kg → 95 kg at 0.4 kg a week, built around school walks, two
 *  upper-body lifting days and rugby on Wednesday and Sunday. */
export const ROAD_TO_95 = `GYMOS PLAN
